/**
 * Gtk4\GrapheneMatrix::to_2d(): ?array
 *
 * Converts a #graphene_matrix_t to an affine transformation matrix, if the given matrix is
 * compatible.
 */
ZEND_METHOD(Gtk4_GrapheneMatrix, to_2d) {
  ZEND_PARSE_PARAMETERS_NONE();
  graphene_matrix_t *self = PHPGTK_BOXED_SELF(graphene_matrix_t);
  double xx = 0;
  double yx = 0;
  double xy = 0;
  double yy = 0;
  double x_0 = 0;
  double y_0 = 0;
  if (!graphene_matrix_to_2d(self, &xx, &yx, &xy, &yy, &x_0, &y_0)) RETURN_NULL();
  array_init_size(return_value, 6);
  {
    zval item;
    ZVAL_DOUBLE(&item, xx);
    add_next_index_zval(return_value, &item);
  }
  {
    zval item;
    ZVAL_DOUBLE(&item, yx);
    add_next_index_zval(return_value, &item);
  }
  {
    zval item;
    ZVAL_DOUBLE(&item, xy);
    add_next_index_zval(return_value, &item);
  }
  {
    zval item;
    ZVAL_DOUBLE(&item, yy);
    add_next_index_zval(return_value, &item);
  }
  {
    zval item;
    ZVAL_DOUBLE(&item, x_0);
    add_next_index_zval(return_value, &item);
  }
  {
    zval item;
    ZVAL_DOUBLE(&item, y_0);
    add_next_index_zval(return_value, &item);
  }
}

