namespace phpgtk {
// MINIT: bind the PHP class to GRAPHENE_TYPE_MATRIX with its field table.
void register_GrapheneMatrix(zend_class_entry *ce) {
  register_boxed(BoxedClass{.type = GRAPHENE_TYPE_MATRIX,
                            .ce = ce,
                            .fields = fields,
                            .read = read,
                            .write = write,
                            .equal = [](gconstpointer a, gconstpointer b) {
                              return graphene_matrix_equal(
                                         static_cast<const graphene_matrix_t *>(a),
                                         static_cast<const graphene_matrix_t *>(b)) != FALSE;
                            }});
}
}  // namespace phpgtk
